import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../../api/axios'; // Import the custom Axios instance you created
import useLogout from '../../hooks/useLogout';
import { PaystackButton } from 'react-paystack';
export default function UserDashboard() {
    const queryClient = useQueryClient();
  const [topUpAmount, setTopUpAmount] = useState('');
  const [isTopUpMode, setIsTopUpMode] = useState(false);
  // TanStack Query handles the state, Axios handles the fetch
  const logout = useLogout();
   const verifyPaymentMutation = useMutation({
    mutationFn: async (reference) => {
      const response = await api.post('/transactions/verify-paystack', { reference });
      return response.data;
    },
    onSuccess: () => {
      // Refresh the dashboard to show the new balance
      queryClient.invalidateQueries(['userDashboardData']);
      setIsTopUpMode(false);
      setTopUpAmount('');
      alert('Wallet funded successfully!');
    },
    onError: () => {
      alert('Payment verification failed. Please contact support.');
    }
  });
  const { data, isLoading, isError } = useQuery({
    queryKey: ['userDashboardData'],
    queryFn: async () => {
      // NOTE: We will need to build this specific endpoint in our Node.js backend next!
      const response = await api.get('/user/dashboard');
      return response.data;
    }
  });

  // 1. Loading State UI
  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
        <p className="mt-4 text-gray-500 font-medium">Loading your wallet...</p>
      </div>
    );
  }


  // The mutation that sends the reference to our backend for verification
 

  // Paystack Configuration object
  const componentProps = {
    email: data?.user?.email || 'customer@example.com', // Get this from your user query
    amount: topUpAmount * 100, // Paystack requires the amount in Kobo
    metadata: {
      name: data?.user?.name,
    },
    publicKey: 'pk_test_your_public_key_here', // Replace with your Paystack Public Key
    text: `Pay ₦${topUpAmount || 0}`,
    onSuccess: (response) => {
      // response.reference is what Paystack gives us upon success
      verifyPaymentMutation.mutate(response.reference);
    },
    onClose: () => alert("Wait! You need to fund your wallet to get points!"),
  };
  // 2. Error State UI
  if (isError) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="bg-red-50 text-red-700 px-6 py-5 rounded-lg shadow-sm border border-red-200 max-w-md w-full">
          <h3 className="font-bold text-lg">Unable to connect</h3>
          <p className="text-sm mt-1">Make sure your Node.js backend server is running on port 5000.</p>
        </div>
      </div>
    );
  }

  // 3. Success State (Data is ready)
  // We use optional chaining (?.) and fallbacks in case the backend payload is missing fields
  const user = data?.user || {
    name: 'Unknown',
    cardUid: '----',
    pointBalance: 0,
    conversionRate: 0,
  };
  
  const transactions = data?.transactions || [];

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Top Navigation */}
     <header className="bg-white shadow-sm">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <h1 className="text-xl font-bold text-indigo-900">MyLoyalty</h1>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold uppercase">
                {user.name.charAt(0)}
              </div>
              <span className="text-sm font-medium text-gray-700 hidden sm:block">Hi, {user.name}</span>
            </div>
            <div className="h-6 w-px bg-gray-300"></div> {/* Visual Divider */}
            <button 
              onClick={() => logout('/user/login')}
              className="text-sm font-medium text-gray-500 hover:text-red-600 transition"
            >
              Log Out
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        
        {/* Virtual Loyalty Card */}
        <div className="bg-gradient-to-r from-indigo-600 to-purple-700 rounded-2xl shadow-lg p-6 sm:p-8 text-white mb-8 relative overflow-hidden">
          <div className="absolute top-0 right-0 -mr-8 -mt-8 w-32 h-32 rounded-full bg-white opacity-10"></div>
          <div className="absolute bottom-0 right-16 -mb-10 w-24 h-24 rounded-full bg-white opacity-10"></div>
          
          <div className="flex justify-between items-start mb-8 relative z-10">
            <div>
              <p className="text-indigo-100 text-sm font-medium uppercase tracking-wider mb-1">Available Balance</p>
              <h2 className="text-4xl sm:text-5xl font-bold">{user.pointBalance} <span className="text-2xl font-medium opacity-80">Pts</span></h2>
            </div>
            <div className="text-right">
              <p className="text-indigo-100 text-sm font-medium mb-1">Card UID</p>
              <p className="font-mono text-lg tracking-widest">{user.cardUid}</p>
            </div>
          </div>
          
          <div className="pt-4 border-t border-indigo-400 border-opacity-40 flex justify-between items-center relative z-10">
            <div>
              <p className="text-indigo-200 text-xs uppercase tracking-wider">Equivalent Value</p>
              <p className="font-medium text-lg">₦{(user.pointBalance * user.conversionRate).toLocaleString()}</p>
            </div>
            <div className="bg-white bg-opacity-20 rounded-lg px-4 py-2 backdrop-blur-sm">
              <p className="text-xs text-white">Status: <span className="font-bold text-green-300">Active</span></p>
            </div>
          </div>
        </div>

        {/* Transaction History */}
        <div className="bg-white shadow-sm rounded-lg border border-gray-200 overflow-hidden">
          <div className="px-6 py-5 border-b border-gray-200">
            <h3 className="text-lg font-medium text-gray-900">Recent Transactions</h3>
          </div>
          
          <div className="divide-y divide-gray-100">
            {transactions.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                No transactions found yet.
              </div>
            ) : (
              transactions.map((tx) => (
                <div key={tx._id || tx.id} className="p-6 flex items-center justify-between hover:bg-gray-50 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                      tx.type === 'topup' ? 'bg-green-100 text-green-600' : 'bg-indigo-100 text-indigo-600'
                    }`}>
                      {tx.type === 'topup' ? '+' : '-'}
                    </div>
                    <div>
                      {/* Assuming the backend populates the company details */}
                      <p className="text-sm font-semibold text-gray-900">{tx.companyId?.name || 'Unknown Merchant'}</p>
                      <p className="text-xs text-gray-500">
                        {new Date(tx.timestamp || tx.date).toLocaleDateString()} • {tx.type === 'topup' ? 'Top-Up' : 'Purchase'}
                      </p>
                    </div>
                  </div>
                  
                  <div className="text-right">
                    <p className={`text-sm font-bold ${tx.type === 'topup' ? 'text-green-600' : 'text-gray-900'}`}>
                      {tx.type === 'topup' ? '+' : '-'}{tx.pointsInvolved || tx.points} Pts
                    </p>
                    <p className="text-xs text-gray-500">₦{(tx.fiatValueNaira || tx.amount).toLocaleString()}</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

      </main>
    </div>
  );
}
